package it.polimi.ingsw.am14.network;

import it.polimi.ingsw.am14.network.messages.events.Event;
/**
 * Represents an observer in the Observer design pattern.
 * Classes implementing this interface can be registered to listen for and react to
 * specific events generated by observable subjects (e.g., the game model).
 */
public interface Observer {
    /**
     * Receives an update notification from the observed subject.
     *
     * @param event the {@link Event} that was triggered or dispatched, carrying the update information.
     */

    void update(Event event);
}
